class Solution:
    def isPalindrome(self, s: str) -> bool:
        l, r = 0, len(s) - 1
        while l < r:
            if not s[l].isalnum():
                l += 1  # viz:skip_l
            elif not s[r].isalnum():
                r -= 1  # viz:skip_r
            elif s[l].lower() != s[r].lower():  # viz:compare
                return False  # viz:mismatch
            else:
                l += 1  # viz:match
                r -= 1
        return True  # viz:done
